  async function load(){try{const params=new URLSearchParams();if(q)params.set("q",q);if(status)params.set("status",status);const r=await apiRequest<{data?:any[]}>(`/admin/queries?${params}`);setItems(r.data||[]);if(selected){const n=(r.data||[]).find(x=>x._id===selected._id);if(n)setSelected(n)}}catch(e){toast.error(e instanceof Error?e.message:"Unable to load queries")}finally{setPageLoading(false);}}
  useEffect(()=>{void load()},[]);
  const stats={total:items.length,new:items.filter(x=>x.status==="new").length,progress:items.filter(x=>x.status==="in_progress").length,resolved:items.filter(x=>x.status==="resolved").length};
