              <svg width="48" height="48" fill="none" viewBox="0 0 24 24"><path d="M9 12h6m-6 4h6M7 4H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2h-2" stroke="#c8d0dc" strokeWidth="1.5" strokeLinecap="round"/><rect x="7" y="2" width="10" height="4" rx="1" stroke="#c8d0dc" strokeWidth="1.5"/></svg>
